#nullable enable
using System.Net;
using System.Net.Sockets;

namespace BinaryCompression.Bench;

/// <summary>
/// Transparent loopback relay that counts bytes successfully forwarded in each
/// direction. Counts include connection negotiation, dictionary traffic, and
/// transport acknowledgements carried in application socket data. IP/TCP/UDP
/// headers and TCP acknowledgements generated by the operating system are excluded.
/// </summary>
internal sealed class TrafficProxy : IAsyncDisposable
{
    internal enum Transport { Tcp, Udp }

    private const int SocketBufferBytes = 8 * 1024 * 1024;
    private readonly CancellationTokenSource stop = new();
    private readonly object socketGate = new();
    private readonly Socket? listener;
    private readonly UdpClient? udpDownstream;
    private readonly UdpClient? udpUpstream;
    private readonly Task worker;
    private Socket? tcpDownstream;
    private Socket? tcpUpstream;
    private IPEndPoint? udpClient;
    private Exception? failure;
    private long clientToServerBytes;
    private long serverToClientBytes;
    private long clientToServerPackets;
    private long serverToClientPackets;
    private int disposed;

    internal int Port { get; }
    internal long ClientToServerBytes => Interlocked.Read(ref clientToServerBytes);
    internal long ServerToClientBytes => Interlocked.Read(ref serverToClientBytes);

    // UDP: forwarded datagrams. TCP: successful send calls, not physical packets.
    internal long ClientToServerPackets => Interlocked.Read(ref clientToServerPackets);
    internal long ServerToClientPackets => Interlocked.Read(ref serverToClientPackets);
    internal Exception? Failure => Volatile.Read(ref failure);

    internal TrafficProxy(Transport mode, int upstreamPort)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(upstreamPort, 1);
        ArgumentOutOfRangeException.ThrowIfGreaterThan(upstreamPort, ushort.MaxValue);
        var server = new IPEndPoint(IPAddress.Loopback, upstreamPort);

        switch (mode)
        {
            case Transport.Tcp:
                listener = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
                listener.Bind(new IPEndPoint(IPAddress.Loopback, 0));
                listener.Listen(1);
                Port = ((IPEndPoint)listener.LocalEndPoint!).Port;
                worker = GuardAsync(() => RunTcpAsync(server));
                break;
            case Transport.Udp:
                udpDownstream = CreateUdpSocket();
                udpUpstream = CreateUdpSocket();
                Port = ((IPEndPoint)udpDownstream.Client.LocalEndPoint!).Port;
                worker = Task.WhenAll(
                    GuardAsync(() => ForwardUdpAsync(udpDownstream, udpUpstream, server, true)),
                    GuardAsync(() => ForwardUdpAsync(udpUpstream, udpDownstream, server, false)));
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(mode));
        }
    }

    internal (long up, long down, long upPackets, long downPackets) Snapshot() =>
        (ClientToServerBytes, ServerToClientBytes, ClientToServerPackets, ServerToClientPackets);

    private static UdpClient CreateUdpSocket()
    {
        var socket = new UdpClient(AddressFamily.InterNetwork);
        socket.Client.ReceiveBufferSize = SocketBufferBytes;
        socket.Client.SendBufferSize = SocketBufferBytes;
        socket.Client.Bind(new IPEndPoint(IPAddress.Loopback, 0));
        return socket;
    }

    private async Task RunTcpAsync(IPEndPoint server)
    {
        var downstream = await listener!.AcceptAsync(stop.Token).ConfigureAwait(false);
        var upstream = new Socket(AddressFamily.InterNetwork, SocketType.Stream, ProtocolType.Tcp);
        lock (socketGate)
        {
            if (stop.IsCancellationRequested)
            {
                downstream.Dispose();
                upstream.Dispose();
                return;
            }
            tcpDownstream = downstream;
            tcpUpstream = upstream;
        }

        downstream.NoDelay = true;
        upstream.NoDelay = true;
        await upstream.ConnectAsync(server, stop.Token).ConfigureAwait(false);
        await Task.WhenAll(
            GuardAsync(() => ForwardTcpAsync(downstream, upstream, true)),
            GuardAsync(() => ForwardTcpAsync(upstream, downstream, false))).ConfigureAwait(false);
    }

    private async Task ForwardTcpAsync(Socket input, Socket output, bool toServer)
    {
        var buffer = new byte[64 * 1024];
        while (!stop.IsCancellationRequested)
        {
            int received = await input.ReceiveAsync(buffer.AsMemory(), SocketFlags.None, stop.Token)
                .ConfigureAwait(false);
            if (received == 0)
            {
                // Preserve a clean TCP half-close while allowing replies to drain.
                try { output.Shutdown(SocketShutdown.Send); }
                catch (SocketException) { }
                catch (ObjectDisposedException) { }
                return;
            }

            int offset = 0;
            while (offset < received)
            {
                int sent = await output.SendAsync(buffer.AsMemory(offset, received - offset),
                    SocketFlags.None, stop.Token).ConfigureAwait(false);
                if (sent == 0)
                    throw new IOException("The TCP relay could not forward socket data.");
                Count(sent, toServer);
                offset += sent;
            }
        }
    }

    private async Task ForwardUdpAsync(UdpClient input, UdpClient output, IPEndPoint server, bool toServer)
    {
        while (!stop.IsCancellationRequested)
        {
            UdpReceiveResult packet = await input.ReceiveAsync(stop.Token).ConfigureAwait(false);
            if (toServer)
                Volatile.Write(ref udpClient, packet.RemoteEndPoint);
            else if (!packet.RemoteEndPoint.Equals(server))
                throw new IOException("The UDP relay received a datagram from an unexpected server endpoint.");

            IPEndPoint? target = toServer ? server : Volatile.Read(ref udpClient);
            if (target is null)
                throw new IOException("The UDP relay received a reply before a client datagram.");

            int sent = await output.SendAsync(packet.Buffer.AsMemory(), target, stop.Token).ConfigureAwait(false);
            Count(sent, toServer);
            if (sent != packet.Buffer.Length)
                throw new IOException("The UDP relay did not forward a complete datagram.");
        }
    }

    private void Count(int bytes, bool toServer)
    {
        if (toServer)
        {
            Interlocked.Add(ref clientToServerBytes, bytes);
            Interlocked.Increment(ref clientToServerPackets);
        }
        else
        {
            Interlocked.Add(ref serverToClientBytes, bytes);
            Interlocked.Increment(ref serverToClientPackets);
        }
    }

    private async Task GuardAsync(Func<Task> operation)
    {
        try { await operation().ConfigureAwait(false); }
        catch (OperationCanceledException) when (stop.IsCancellationRequested) { }
        catch (ObjectDisposedException) when (stop.IsCancellationRequested) { }
        catch (SocketException) when (stop.IsCancellationRequested) { }
        catch (Exception error)
        {
            Interlocked.CompareExchange(ref failure, error, null);
            StopAndClose();
        }
    }

    private void StopAndClose()
    {
        stop.Cancel();
        listener?.Dispose();
        udpDownstream?.Dispose();
        udpUpstream?.Dispose();
        lock (socketGate)
        {
            tcpDownstream?.Dispose();
            tcpUpstream?.Dispose();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (Interlocked.Exchange(ref disposed, 1) == 0)
        {
            StopAndClose();
            await worker.ConfigureAwait(false);
            stop.Dispose();
        }
        else
        {
            await worker.ConfigureAwait(false);
        }
    }
}
